// Three waves per newly opened region; old regions and saved receipts remain valid.
let guildAdvancedBoard=false;
function guildRegionOpeningRank(region){return region<10?region+1:region===10?20:30;}
function guildRegionStage(region,c=campaign()){const rank=c.rank||1,opening=guildRegionOpeningRank(region);if(rank>opening)return 3;const needed=rank<10?promotionXP(rank):veteranXP(rank),xp=c.rankXP||0;return xp>=Math.ceil(needed*2/3)?3:xp>=Math.ceil(needed/3)?2:1;}
function guildWaveAllowed(q,c){if(!q)return false;if(c.questDone.includes(q.id)||c.contract?.id===q.id)return true;if(!['hunt','boss'].includes(q.kind))return true;const r=REGIONS[q.region],stage=guildRegionStage(q.region,c);if(q.kind==='hunt'){const i=r.enemies.findIndex(s=>s.id===q.target);return i>=0&&i<([0,2,5,8][stage]);}const i=r.bosses.findIndex(s=>s.id===q.target);return i>=0&&(stage===3||stage===2&&i<2);}
const stagedQuestEligibleBase=guildQuestEligible;guildQuestEligible=(q,c,history=false)=>stagedQuestEligibleBase(q,c,history)&&(history||guildWaveAllowed(q,c));
const stagedBoardBase=guildBoardQuests;guildBoardQuests=region=>{let quests=stagedBoardBase(region).filter(q=>guildQuestAllowed(q));quests=quests.filter(q=>guildAdvancedBoard?['secret','ex'].includes(q.kind):!['secret','ex'].includes(q.kind));if(!quests.length&&guildAdvancedBoard){guildAdvancedBoard=false;return guildBoardQuests(region);}return quests.sort((a,b)=>(a.kind==='trial'?-1:0)-(b.kind==='trial'?-1:0)||Number(campaign().questDone.includes(a.id))-Number(campaign().questDone.includes(b.id)));};
function guildRecommended(region=campaign().unlocked){return guildBoardQuests(region)[0]||null;}
const stagedVillageBase=showVillage;showVillage=(region=campaign().region)=>{if(villageOpen&&!campaign().contract)guildBoardSelection=null;const result=stagedVillageBase(region);if(menuSurface!=='village'||!villageOpen||campaign().contract)return result;const c=campaign(),stage=guildRegionStage(region),needed=c.rank<10?promotionXP(c.rank):veteranXP(c.rank),next=stage<3?Math.ceil(needed*stage/3):0,board=$('card').querySelector('.guild-board');if(board){const hint=document.createElement('section');hint.className='guild-wave-summary';hint.innerHTML='<b>依頼の解放 '+stage+' / 3</b><span>'+(stage<3?'次の解放まで '+Math.max(0,next-c.rankXP)+' ランクXP':'この地域の通常依頼はすべて解放')+'</span>';board.before(hint);const first=$('card').querySelector('[data-guild-quest]');if(first){const label=document.createElement('small');label.className='guild-recommended';label.textContent='おすすめ';first.prepend(label);}const advanced=[...EX_BOSSES.map(s=>guildQuest('ex:'+s.id)),guildQuest('secret:'+REGIONS[region].secret.id)].some(q=>guildQuestAllowed(q));if(advanced){const toggle=document.createElement('button');toggle.textContent=guildAdvancedBoard?'通常の依頼へ':'高難度の依頼';toggle.onclick=()=>{guildAdvancedBoard=!guildAdvancedBoard;showVillage(region);};hint.append(toggle);}}return result;};
GAME_TIPS[5][2]='依頼を受ける → 指定の敵を討伐 → 落ちた素材を回収 → 生還して報告 → 素材とゴールドで装備製作。ランク内のXPに応じて依頼は3段階で増えます。敗北・目標未達成での帰還は依頼失敗。おすすめ依頼から進め、昇格試験を目指しましょう。';
